export type ImportActionCode =
  | "adobe_fonts_kit"
  | "placeholder_text"
  | "store_detected"
  | "assets_skipped"
  | "embeds_dropped"
  | "motion_rebuilt"
  | "contact_missing"
  | "design_not_measured"
  | "source_barely_readable";

export type ImportActionSeverity = "blocker" | "action" | "info";

export type ImportAction = {
  code: ImportActionCode;
  severity: ImportActionSeverity;
  /** One line, imperative: what the owner should do. */
  title: string;
  /** One or two sentences: why, and what happens if they don't. */
  detail: string;
  /** Where it gets done, in the owner's words. Absent when it is off-product
   *  (an Adobe Fonts account) or purely informational. */
  where?: string;
};

/** How readable the served document was. */
export type SourceContentQuality = {
  /** Words of visible text in the HTML as served (scripts/styles removed). */
  words: number;
  /** True when there is far too little text for this to be a real page. */
  thin: boolean;
  /** The client-side builder or framework whose empty shell we recognised.
   *  Absent when the page is thin for some other reason - we name the tool only
   *  when we are actually sure which one it is. */
  shell?: string;
};

/** Client-rendered shells, most specific first. Each entry is [label, marker].
 *  The label is shown to the owner, so it names the product they know. */
const SHELL_SIGNALS: Array<[string, RegExp]> = [
  ["Wix", /\bwix-|static\.wixstatic\.com|_wixCssStates\b/i],
  ["Squarespace", /squarespace\.com|static1\.squarespace|Static\.SQUARESPACE_CONTEXT/i],
  ["Next.js", /id=["']__next["']|__NEXT_DATA__/i],
  ["Nuxt", /__NUXT__|id=["']__nuxt["']/i],
  ["Gatsby", /id=["']___gatsby["']/i],
  ["Angular", /\bng-version=|<app-root\b/i],
  ["Vue", /id=["']app["'][^>]*>\s*<\/div>|data-v-app/i],
  ["React", /data-reactroot|id=["']root["'][^>]*>\s*<\/div>/i],
];

/** Visible words in the document as served. Scripts, styles, SVG and comments
 *  are removed first: a React bundle is a megabyte of "text" that no visitor
 *  ever reads, and counting it would hide exactly the pages this is for. */
export function readableWordCount(html: string): number {
  const text = html
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<(script|style|noscript|svg|template)\b[\s\S]*?<\/\1>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&[a-z]+;|&#\d+;/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
  return text ? text.split(" ").filter((w) => w.length > 1).length : 0;
}

/** Below this a page cannot be a real small-business page. A genuinely short
 *  contact page still clears it comfortably; a framework shell does not come
 *  close. Deliberately generous - a false "your site is empty" is worse than a
 *  missed one. */
export const THIN_WORDS = 60;

export function assessSourceContent(html: string): SourceContentQuality {
  const words = readableWordCount(html);
  const thin = words < THIN_WORDS;
  // Only name a shell when the page is ALSO thin. A server-rendered Next.js
  // site carries `__NEXT_DATA__` and all of its text, and telling that owner
  // their page "builds itself in the browser" would be wrong and alarming.
  const shell = thin ? SHELL_SIGNALS.find(([, re]) => re.test(html))?.[0] : undefined;
  return { words, thin, ...(shell ? { shell } : {}) };
}

/** What we could actually observe on the source page. Everything is a count or
 *  a concrete id so no downstream label has to hedge. */
export type SourceSignals = {
  /** Adobe Fonts (Typekit) kit ids the page loaded, e.g. ["wyt4frb"]. */
  adobeKitIds: string[];
  /** Motion libraries / attribute conventions detected, e.g. ["GSAP"]. */
  motionLibs: string[];
  /** Third-party embeds (iframes) that could not come over. */
  embeds: number;
  /** Template placeholder runs still present in the copy ("Lorem ipsum"). */
  placeholders: number;
  /** How much readable text the SERVED document actually carried, and whether
   *  it looks like a page that builds itself in the browser. A site behind a
   *  client-side framework serves a near-empty shell to a fetcher, so the
   *  import "succeeds" and produces a business name and nothing else - the
   *  worst outcome in the product, and until now a completely silent one. */
  content?: SourceContentQuality;
  /** Evidence that the owner already sells online (see detectCommerce.ts).
   *  `null` when nothing was detected. Optional so callers that assemble their
   *  own signal object across a crawl keep compiling; those simply produce no
   *  store action. Detection only - nothing here activates commerce. */
  commerce?: CommerceDetection | null;
};

export const EMPTY_SIGNALS: SourceSignals = {
  adobeKitIds: [],
  motionLibs: [],
  embeds: 0,
  placeholders: 0,
  commerce: null,
};

// use.typekit.net/<kit>.js|css, and the older //use.typekit.com/<kit>.js form.
const TYPEKIT_RE = /use\.typekit\.(?:net|com)\/([a-z0-9]+)\.(?:js|css)/gi;
const IFRAME_RE = /<iframe\b/gi;
// "Lorem ipsum" is the near-universal marker of an untouched template block
// (page-builder templates ship it); matching the two words together avoids flagging a
// page that happens to use the word "lorem" in prose.
const PLACEHOLDER_RE = /lorem\s+ipsum/gi;

/** Motion signals, most specific first. Each entry is [label, detector]. The
 *  label is shown to the owner, so it names the library, not the file. */
const MOTION_SIGNALS: Array<[string, RegExp]> = [
  ["GSAP", /\bgsap(?:\.min)?\.js|cdnjs[^"']*gsap/i],
  ["ScrollTrigger", /ScrollTrigger(?:\.min)?\.js/i],
  ["Lenis", /\blenis(?:\.min)?\.js/i],
  ["AOS", /\baos(?:\.min)?\.(?:js|css)|\bdata-aos=/i],
  ["Webflow", /\bdata-w-id=|\banimation-(?:fade|scroll)-/i],
  ["Framer Motion", /framer-motion/i],
];

const countOf = (html: string, re: RegExp) => (html.match(re) ?? []).length;

/**
 * Read a source page for everything the import can honestly act on. Cheap
 * regex only (no DOM): this runs inside a Convex action alongside the rest of
 * the import, and every signal is a "did we see this string" question.
 */
export function detectSourceSignals(
  html: string,
  css: string | string[] = [],
  /** The page's own URL. Optional: without it a cart link only counts when it
   *  is relative, because an absolute one could be somebody else's shop. */
  baseUrl?: string,
): SourceSignals {
  const styles = Array.isArray(css) ? css.join("\n") : css;
  const all = `${html}\n${styles}`;

  const adobeKitIds = [
    ...new Set([...html.matchAll(TYPEKIT_RE)].map((m) => m[1].toLowerCase())),
  ];
  const motionLibs = MOTION_SIGNALS.filter(([, re]) => re.test(all)).map(([label]) => label);

  return {
    adobeKitIds,
    motionLibs,
    embeds: countOf(html, IFRAME_RE),
    placeholders: countOf(html, PLACEHOLDER_RE),
    content: assessSourceContent(html),
    commerce: detectCommerce({ html, baseUrl }),
  };
}

